'use client';
import { useEffect, useRef, useState } from 'react';
import { Brain, Palette, ScanEye, Server, Sparkles, type LucideIcon } from 'lucide-react';

const ICONS: Record<string, LucideIcon> = { brain: Brain, sparkles: Sparkles, server: Server, scan: ScanEye, palette: Palette };
export interface SkillRow { name: string; label: string; pct: number }

/** Skill group card whose progress bars fill (with a light sweep) when the card scrolls into view. */
export function SkillCard({ title, icon, items }: { title: string; icon: string; items: SkillRow[] }) {
  const ref = useRef<HTMLDivElement>(null);
  const [on, setOn] = useState(false);
  useEffect(() => {
    const el = ref.current; if (!el) return;
    const io = new IntersectionObserver(([e]) => { if (e.isIntersecting) { setOn(true); io.disconnect(); } }, { threshold: 0.3 });
    io.observe(el); return () => io.disconnect();
  }, []);
  const Icon = ICONS[icon] ?? Sparkles;
  return (
    <div ref={ref} className={`glass pad skill-card${on ? ' on' : ''}`}>
      <div className="card-head"><span className="icon-chip"><Icon size={22} /></span><h3>{title}</h3></div>
      <ul className="skill-list">
        {items.map((s, i) => (
          <li key={s.name}>
            <div className="skill-row"><span>{s.name}</span><span className="skill-level">{s.label}</span></div>
            <div className="track" role="progressbar" aria-label={s.name} aria-valuemin={0} aria-valuemax={100} aria-valuenow={s.pct} aria-valuetext={s.label}>
              <span className="fill" style={{ transform: on ? `scaleX(${s.pct / 100})` : 'scaleX(0)', transitionDelay: `${i * 90}ms` }} />
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
}
